            pts_seconds = float(packet.pts * packet.time_base)
            rr.set_time("time", duration=pts_seconds)
            rr.log(
                "audio_stream",
                rr.AudioStream.from_fields(chunk=bytes(packet), duration_samples=packet.duration),
            )

